SELECT CASE WHEN customers.age >= 59 THEN 'high' WHEN customers.age >= 39 THEN 'mid' ELSE 'low' END AS age_bucket, DATE_FORMAT(customers.signup_date, 'yyyy-MM') AS signup_month, COUNT(DISTINCT sessions.device) AS unique_devices FROM sessions JOIN customers ON sessions.customer_id = customers.id GROUP BY CASE WHEN customers.age >= 59 THEN 'high' WHEN customers.age >= 39 THEN 'mid' ELSE 'low' END, DATE_FORMAT(customers.signup_date, 'yyyy-MM') HAVING COUNT(DISTINCT sessions.device) > 4 ORDER BY unique_devices, age_bucket, signup_month LIMIT 10
